// "gen" backend: gen/uds_chip_gen.h, straight-line C++ generated by
// engine/gen.py from the Yosys netlist (one step() per clock, state in plain
// integers). step() computes the outputs before the clock edge, so after it
// they are the pins during the cycle just clocked.
//
// SPDX-License-Identifier: Apache-2.0
#pragma once
#include "gen/uds_chip_gen.h"

#define BACKEND_NAME "gen"
#define BACKEND_ID 3

namespace backend {

uint8_t uo = 0, uio = 0;

inline void init() {
  gen::in_ena = 1;
  gen::in_ui_in = 0;
  gen::in_clk = 1;
}
inline void set_rst_n(bool v) { gen::in_rst_n = v; }

__attribute__((always_inline)) inline void clock(uint8_t uio_in) {
  gen::in_uio_in = uio_in;
  gen::step();
  uo = uint8_t(gen::out_uo_out);
  uio = uint8_t(gen::out_uio_out);
}

}  // namespace backend
